import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const container = new THREE.Group();
  container.position.set(-1.25, -1.1, 0);
  container.rotation.set(0, 0, 0);
  container.scale.set(1, 1, 1);

  // Load GLB mesh from cache
  const gltf = ctx.glbLoader.load(config.meshUrl);
  const mesh = gltf.scene || gltf;
  container.add(mesh);

  // Apply cinematic primitives from config
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(primitive => {
      ctx.primitives[primitive.name](container, primitive.params);
    });
  }

  // Initialize event handlers
  container.userData.handlers = {};

  let hoverTimeline = null;
  const originalY = container.position.y;

  // Hover interaction: rise-in effect (0.15 unit displacement)
  container.userData.handlers.onHover = (isHovering) => {
    if (hoverTimeline) hoverTimeline.kill();

    if (isHovering) {
      hoverTimeline = gsap.to(container.position, {
        y: originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
    } else {
      hoverTimeline = gsap.to(container.position, {
        y: originalY,
        duration: 0.7,
        ease: 'power3.out'
      });
    }
  };

  // Click interaction: emit hub-features.select event
  container.userData.handlers.onClick = () => {
    if (ctx.emit) {
      ctx.emit('hub-features.select', {});
    }
  };

  // Cleanup resources
  container.userData.cleanup = () => {
    if (hoverTimeline) {
      hoverTimeline.kill();
    }

    container.traverse((child) => {
      if (child.geometry) {
        child.geometry.dispose();
      }
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(mat => mat.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return container;
}
